  container: "viewDiv",
  map
});

const promise = Layer.fromPortalItem({
  portalItem: {
    id: "2e2f6840647d4cb9a384532652e5100f"
  }
});
promise.then((layer) => {
  console.log(layer.type); // "map-notes"
  map.add(layer);

  Promise.all([view.when(), layer.load()]).then(() => {
    view.goTo(layer.fullExtent);
  });
});

