const DPI = 96
const inchesPerMeter = 39.37;

// Get the scale for an extent
function getScale(extent, viewWidth) {
  const unitValue = extent.spatialReference.metersPerUnit;
  return (extent.width / viewWidth) * unitValue * inchesPerMeter * DPI;
}

